mapper.select:
SELECT id
FROM public.nocode_work_draft
WHERE creator = #{actor}
AND source_type = #{source}
AND source_id = #{sourceId}
AND state = #{state}
AND deleted = 0
ORDER BY update_time DESC, id DESC
LIMIT 1

SELECT id, create_time AS created_at
FROM public.nocode_work_draft
WHERE creator = #{actor}
AND deleted = 0
AND source_type = #{source}
AND resource_json ->> 'applicationId' = #{query.applicationId}
AND state = #{query.state}

    AND (create_time, id) <(CAST(#{query.before.createdAt} AS timestamp), #{query.before.id})

ORDER BY create_time DESC, id DESC
LIMIT #{count}

SELECT id, source_id, create_time AS created_at
FROM public.nocode_work_draft
WHERE creator = #{actor}
AND deleted = 0
AND source_type = #{source}
AND state = #{query.state}

    AND (create_time, id) <(CAST(#{query.before.createdAt} AS timestamp), #{query.before.id})

ORDER BY create_time DESC, id DESC
LIMIT #{count}

SELECT *
FROM public.nocode_work_draft
WHERE id = #{id}
AND creator = #{actor}
AND deleted = 0
FOR UPDATE

mapper.update:
UPDATE public.nocode_work_draft
SET values_json = CAST(#{row.valuesJson} AS jsonb), details_json = CAST(#{row.detailsJson} AS jsonb),
related_json = CAST(#{row.relatedJson} AS jsonb), base_record_revision = #{row.baseRecordRevision}, lock_version = lock_version + 1,
updater = #{actor}, update_time = clock_timestamp()
WHERE id = #{row.id}
AND creator = #{actor}
AND deleted = 0
AND state = #{state}
AND lock_version = #{expected}

UPDATE public.nocode_work_draft
SET state = #{next}, lock_version = lock_version + 1, updater = #{actor}, update_time = clock_timestamp()
WHERE id = #{id}
AND creator = #{actor}
AND deleted = 0
AND state = #{current}
AND lock_version = #{expected}
